CREATE OR REPLACE FUNCTION calculate_fei(
    engrade numeric,
    socintscore numeric,
    actdayswk integer,
    avgsesscount integer
) RETURNS numeric AS $$
BEGIN
    RETURN (engrade * 0.4) + ((socintscore / 100.0) * 0.3) + ((actdayswk::numeric / 7.0) * 0.2) + ((avgsesscount::numeric / 10.0) * 0.1);
END;
$$ LANGUAGE plpgsql;
